INSERT INTO articles VALUES(1,1,'Gartner: Top Trends in Human Resources for 2026','https://www.gartner.com/en/human-resources/trends',unistr('안녕하세요! HR/L&D 전문 콘텐츠 큐레이터로서 요청하신 가트너 아티클의 상세 정리본을 작성해 드리겠습니다.\u000a\u000a다만, 제공해주신 본문 내용에 ''[페이지 로드 실패: Request failed with status code 403]''이라는 메시지가 있어 아티클의 실제 내용을 확인할 수 없었습니다. 해당 오류로 인해 아티클 본문에 접근할 수 없었기에, 요청하신 핵심 요약, 주요 인사이트, HR/L&D 실무 적용, 핵심 개념 등을 작성해 드릴 수 없는 상황입니다.\u000a\u000a번거로우시겠지만, 아티클의 실제 내용을 복사하여 다시 제공해주시거나 접근 가능한 URL을 알려주시면 요청하신 형식에 맞춰 상세 정리본을 작성해 드리겠습니다.\u000a\u000a콘텐츠를 기다리겠습니다!'),'',0,'2026-03-07','2026-03-07 00:19:41','2026-03-07 07:44:29',0);
