INSERT INTO articles VALUES(19,1,'McKinsey의 ''The hidden power of social networks''','https://www.mckinsey.com/capabilities/people-and-organizational-performance/our-insights/the-hidden-power-of-social-networks',unistr('AI 리포팅:\u000a\u000aPrompt: "내가 방금 ONA 분석을 했는데, A부서장(Mgr)보다 B부서의 대리(Sr)가 소통 중심성이 2배 높게 나왔어. 이 데이터를 근거로 ''비공식 리더(Unofficial Leader) 활용 방안''에 대한 보고서 초안을 HRD 전문가 관점에서 작성해줘. (출처: McKinsey의 ''The hidden power of social networks'' 인용)"'),'',0,'2026-03-07','2026-03-07 00:19:41',NULL,0);
